const installationId = $json.installation_id;
const entrada = $json.inicio;

if (!Number.isSafeInteger(installationId) || installationId <= 0) {
  throw new Error(
    'Configure o installation_id real no nó 01 antes de consultar.'
  );
}

if (typeof entrada !== 'string') {
  throw new Error('inicio deve ser uma string AAAA-MM-DD ou vazia.');
}

const valor = entrada.trim();
let inicio;

if (valor === '') {
  const agora = new Date();

  inicio = new Date(Date.UTC(
    agora.getUTCFullYear(),
    agora.getUTCMonth(),
    agora.getUTCDate()
  ));

  const diasDesdeSegunda = (inicio.getUTCDay() + 6) % 7;
  inicio.setUTCDate(inicio.getUTCDate() - diasDesdeSegunda - 7);
} else {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(valor)) {
    throw new Error('inicio deve estar no formato AAAA-MM-DD.');
  }

  inicio = new Date(valor + 'T00:00:00Z');

  if (
    !Number.isFinite(inicio.getTime()) ||
    inicio.toISOString().slice(0, 10) !== valor
  ) {
    throw new Error('A data informada não existe.');
  }
}

const fim = new Date(inicio);
fim.setUTCDate(fim.getUTCDate() + 7);

return {
  json: {
    installation_id: installationId,
    inicio: inicio.toISOString().slice(0, 10),
    fim: fim.toISOString().slice(0, 10),
  },
};

const crypto = require('crypto');

const segredo = $env.N8N_SEGREDO_ACOES;

if (!segredo) {
  throw new Error('N8N_SEGREDO_ACOES indisponível no ambiente.');
}

const base = (
  $env.APROVA_API_URL || 'http://host.docker.internal:8080'
).replace(/\/+$/, '');

const query =
  'installation_id=' + $json.installation_id +
  '&inicio=' + $json.inicio;

const timestamp = Math.floor(Date.now() / 1000).toString();

const assinatura = 'sha256=' + crypto
  .createHmac('sha256', segredo)
  .update(timestamp + '.' + query)
  .digest('hex');

return {
  json: {
    installation_id: $json.installation_id,
    inicio: $json.inicio,
    fim: $json.fim,
    requisicao: {
      url: base + '/reports/weekly?' + query,
      headers: {
        'X-Aprova-Timestamp': timestamp,
        'X-Aprova-Assinatura': assinatura,
      },
    },
  },
};

const consulta = $('03 | Assinar Consulta').item.json;

const indisponivel = () => ({
  json: {
    status: 'indisponivel',
    mensagem: 'Não foi possível obter um relatório válido da API.',
    periodo_solicitado: {
      inicio: consulta.inicio,
      fim_exclusivo: consulta.fim,
      fuso: 'UTC',
    },
    dados: null,
  },
});

const r = $json.body ?? $json.data;

if (
  $json.statusCode !== 200 ||
  !r ||
  typeof r !== 'object' ||
  Array.isArray(r)
) {
  return indisponivel();
}

const campos = [
  'total_execucoes',
  'concluidas',
  'rejeitadas',
  'falhas',
  'em_andamento',
  'exigiram_aprovacao_humana',
  'risco_medio',
  'revertidas',
];

if (
  r.installation_id !== consulta.installation_id ||
  r.inicio !== consulta.inicio + 'T00:00:00Z' ||
  r.fim !== consulta.fim + 'T00:00:00Z' ||
  campos.some(c => !Number.isSafeInteger(r[c]) || r[c] < 0)
) {
  return indisponivel();
}

const finalizadas = r.concluidas + r.rejeitadas + r.falhas;

if (
  finalizadas + r.em_andamento !== r.total_execucoes ||
  r.exigiram_aprovacao_humana > r.total_execucoes ||
  r.risco_medio > r.total_execucoes
) {
  return indisponivel();
}

const taxaValida = finalizadas === 0
  ? r.taxa_sucesso === null
  : typeof r.taxa_sucesso === 'number' &&
    Number.isFinite(r.taxa_sucesso) &&
    Math.abs(r.taxa_sucesso - r.concluidas / finalizadas) <= 0.000001;

if (!taxaValida) {
  return indisponivel();
}

return {
  json: {
    status: 'disponivel',
    installation_id: r.installation_id,
    periodo: {
      inicio: r.inicio,
      fim_exclusivo: r.fim,
      fuso: 'UTC',
    },
    dados: {
      ...Object.fromEntries(campos.map(c => [c, r[c]])),
      taxa_sucesso: r.taxa_sucesso,
    },
  },
};
